import { Component, OnInit, ViewChild } from '@angular/core';
import { DocumentsService } from '../../../services/documents.service';
import { DocumentItem, DocumentModel, DocumentType, DocumentSource, DocumentSearchParams } from '../../../models/document.model';
import { TranslationService } from '../../../services/translation.service';
import { ConfirmationModalComponent, ConfirmationModalData } from '../../shared/confirmation-modal/confirmation-modal.component';
import { AddDocument } from '../add-document/add-document';
import { EditDocument } from '../edit-document/edit-document';

@Component({
  selector: 'app-documents-list',
  standalone: false,
  templateUrl: './documents-list.html',
  styleUrl: './documents-list.css'
})
export class DocumentsList implements OnInit {
  @ViewChild('addDocumentModal') addDocumentModal!: AddDocument;
  @ViewChild('editDocumentModal') editDocumentModal!: EditDocument;
  @ViewChild('confirmationModal') confirmationModal!: ConfirmationModalComponent;
  
  allDocuments: DocumentItem[] = [];
  filteredDocuments: DocumentItem[] = [];
  searchTerm: string = '';
  isLoading: boolean = false;
  
  // Pagination
  currentPage = 1;
  pageSize = 9;
  totalCount = 0;
  
  // Filters
  selectedType: number | null = null;
  selectedDocumentSource: number | null = null;
  fromDate: string = '';
  toDate: string = '';

  constructor(
    private documentsService: DocumentsService,
    private translationService: TranslationService
  ) {}

  documentTypes: Record<number, string> = {};
  documentSources: Record<number, string> = {};

  ngOnInit() {
    this.initializeTranslations();
    this.loadDocuments();
  }

  private initializeTranslations() {
    this.documentTypes = {
      0: this.translate('documents.types.0'),
      1: this.translate('documents.types.1'),
      2: this.translate('documents.types.2'),
      3: this.translate('documents.types.3'),
      4: this.translate('documents.types.4'),
      5: this.translate('documents.types.5'),
      6: this.translate('documents.types.6'),
      7: this.translate('documents.types.7'),
      8: this.translate('documents.types.8')
    };

    this.documentSources = {
      0: this.translate('documents.sources.0'),
      1: this.translate('documents.sources.1')
    };
  }

  loadDocuments() {
    this.isLoading = true;
    
    const params: DocumentSearchParams = {
      search: this.searchTerm || undefined,
      type: this.selectedType || undefined,
      documentSource: this.selectedDocumentSource || undefined,
      from: this.fromDate || undefined,
      to: this.toDate || undefined,
      pageSize: this.pageSize,
      pageNumber: this.currentPage
    };
    
    this.documentsService.getAllDocuments(params).subscribe({
      next: (res) => {
        this.allDocuments = res.data.items;
        this.totalCount = res.data.totalCount;
        this.currentPage = res.data.page;
        this.pageSize = res.data.pageSize;
        this.filteredDocuments = [...this.allDocuments];
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Error loading documents:', error);
        this.isLoading = false;
      }
    });
  }

  /**
   * Check if search term is valid
   * Prevents searches starting with '.', space, or single special character
   */
  isValidSearchTerm(searchTerm: string): boolean {
    if (!searchTerm || !searchTerm.trim()) {
      return true; // Empty search is valid
    }
    
    const trimmed = searchTerm.trim();
    
    // Prevent starting with '.' or space
    if (trimmed.startsWith('.') || trimmed.startsWith(' ')) {
      return false;
    }
    
    // Prevent single special character (only one character that is not alphanumeric)
    if (trimmed.length === 1 && !/^[a-zA-Zابتثجحخدذرزسشصضطظعغفقكلمنهويأءآإئؤ0-9]$/.test(trimmed)) {
      return false;
    }
    
    return true;
  }

  /**
   * Handle search input event
   * Cleans invalid characters in real-time
   */
  onSearchInput(event: Event): void {
    const input = event.target as HTMLInputElement;
    const value = input.value;
    
    if (!this.isValidSearchTerm(value)) {
      // Remove invalid starting characters
      let cleanedValue = value.trim();
      
      // Remove leading '.' or space
      while (cleanedValue.startsWith('.') || cleanedValue.startsWith(' ')) {
        cleanedValue = cleanedValue.substring(1).trim();
      }
      
      // If it's a single special character, clear it
      if (cleanedValue.length === 1 && !/^[a-zA-Zابتثجحخدذرزسشصضطظعغفقكلمنهويأءآإئؤ0-9]$/.test(cleanedValue)) {
        cleanedValue = '';
      }
      
      // Update input and searchTerm
      setTimeout(() => {
        input.value = cleanedValue;
        this.searchTerm = cleanedValue;
      }, 0);
    } else {
      this.searchTerm = value;
    }
  }

  onSearchChange() {
    // Validate before searching
    if (!this.isValidSearchTerm(this.searchTerm)) {
      return;
    }
    
    this.currentPage = 1;
    this.loadDocuments();
  }

  onFilterChange() {
    this.currentPage = 1;
    this.loadDocuments();
  }

  /**
   * Handle from date change
   * Validates that to date is not before from date
   */
  onFromDateChange(event: Event): void {
    const target = event.target as HTMLInputElement;
    const fromDateValue = target.value;
    this.fromDate = fromDateValue;
    
    // If to date is before the new from date, clear it
    if (fromDateValue && this.toDate) {
      if (this.toDate < fromDateValue) {
        this.toDate = '';
      }
    }
    
    // Trigger filter if both dates are valid
    if (fromDateValue && this.toDate && this.toDate >= fromDateValue) {
      this.currentPage = 1;
      this.loadDocuments();
    }
  }

  /**
   * Handle to date change
   * Validates that to date is not before from date
   */
  onToDateChange(event: Event): void {
    const target = event.target as HTMLInputElement;
    const toDateValue = target.value;
    
    // Validate that to date is not before from date
    if (toDateValue && this.fromDate && toDateValue < this.fromDate) {
      // Reset to date if it's before from date
      target.value = '';
      this.toDate = '';
      return;
    }
    
    this.toDate = toDateValue;
    
    // Trigger filter if both dates are valid
    if (this.fromDate && toDateValue && toDateValue >= this.fromDate) {
      this.currentPage = 1;
      this.loadDocuments();
    }
  }

  /**
   * Get minimum date for to date input (should be from date if selected)
   */
  getMinToDate(): string {
    return this.fromDate || '';
  }

  onPageChange(page: number) {
    this.currentPage = page;
    this.loadDocuments();
  }

  onPageSizeChange() {
    this.currentPage = 1;
    this.loadDocuments();
  }

  clearFilters() {
    this.searchTerm = '';
    this.selectedType = null;
    this.selectedDocumentSource = null;
    this.fromDate = '';
    this.toDate = '';
    this.currentPage = 1;
    this.loadDocuments();
  }

  getTypeLabel(type: number): string {
    return this.documentTypes[type] || this.translate('documents.unknown');
  }

  getDocumentSourceLabel(source: number): string {
    return this.documentSources[source] || this.translate('documents.unknown');
  }

  openAddModal() {
    this.addDocumentModal.open();
  }

  editDocument(document: DocumentItem) {
    this.editDocumentModal.open(document);
  }

  deleteDocument(id: number, title: string) {
    const confirmData: ConfirmationModalData = {
      title: this.translationService.translate('documents.delete_document'),
      message: this.translationService.translate('documents.confirm_delete_document'),
      confirmText: this.translationService.translate('common.delete'),
      cancelText: this.translationService.translate('common.cancel'),
      type: 'delete'
    };

    this.confirmationModal.show(confirmData);
    
    // Subscribe to confirmation and handle the response
    const subscription = this.confirmationModal.confirm.subscribe(() => {
      
      // User confirmed deletion
      this.documentsService.deleteDocument(id).subscribe({
        next: (res) => {
          // Update local arrays
          this.allDocuments = this.allDocuments.filter(d => d.id !== id);
          this.filteredDocuments = this.filteredDocuments.filter(d => d.id !== id);
          // Update total count
          this.totalCount = Math.max(0, this.totalCount - 1);
          this.showSuccessMessage(this.translationService.translate('documents.delete_document_success'));
          // Unsubscribe to prevent memory leaks
          subscription.unsubscribe();
        },
        error: (error) => {
          console.error('Error deleting document:', error);
          console.error('Error details:', {
            status: error.status,
            statusText: error.statusText,
            error: error.error,
            message: error.message,
            url: error.url
          });
          
          let errorMessage = this.translate('documents.unknown_error');
          if (error.error?.message) {
            errorMessage = error.error.message;
          } else if (error.message) {
            errorMessage = error.message;
          }
          
          // Handle specific error cases
          if (error.status === 400) {
            errorMessage = this.translate('documents.delete_constraint_error');
          } else if (error.status === 404) {
            errorMessage = this.translate('documents.document_not_found');
          } else if (error.status === 500) {
            errorMessage = this.translate('documents.server_error');
          } else if (error.status) {
            errorMessage = `HTTP ${error.status}: ${error.statusText || 'Server Error'}`;
          }
          
          this.showErrorMessage(this.translationService.translate('common.error') + ': ' + errorMessage);
          // Unsubscribe to prevent memory leaks
          subscription.unsubscribe();
        }
      });
    });
  }

  downloadDocument(documentItem: DocumentItem) {
    this.documentsService.downloadDocument(documentItem.id).subscribe({
      next: (blob) => {
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = documentItem.fileName + documentItem.fileExtension;
        link.click();
        window.URL.revokeObjectURL(url);
        this.showSuccessMessage(this.translationService.translate('documents.download_success'));
      },
      error: (error) => {
        console.error('Error downloading document:', error);
        let userFriendlyMessage = '';
        
        // Check error status code
        const statusCode = error.status || (error.error?.status) || 0;
        const errorMessage = (error.message || '').toLowerCase();
        const errorText = (error.error?.message || error.error?.error || '').toLowerCase();
        
        // Check if the error is a 400 or 404 (file not found)
        // This handles cases like "400 OK", "not found", "NotFound", etc.
        if (statusCode === 400 || statusCode === 404 ||
            errorMessage.includes('400') || errorMessage.includes('404') ||
            errorMessage.includes('not found') || errorMessage.includes('notfound') ||
            errorText.includes('not found') || errorText.includes('notfound') ||
            errorText.includes('file not found') || errorText.includes('document not found')) {
          userFriendlyMessage = this.translationService.translate('documents.file_not_found');
        } else if (statusCode === 500 || errorMessage.includes('500')) {
          userFriendlyMessage = this.translationService.translate('documents.download_server_error');
        } else if (statusCode === 403 || errorMessage.includes('403') || errorMessage.includes('forbidden')) {
          userFriendlyMessage = this.translationService.translate('documents.download_permission_denied');
        } else {
          userFriendlyMessage = this.translationService.translate('documents.download_error');
        }
        
        this.showErrorMessage(userFriendlyMessage);
      }
    });
  }

  showSuccessMessage(message: string) {
    const successData: ConfirmationModalData = {
      title: this.translationService.translate('common.success'),
      message: message,
      confirmText: this.translationService.translate('common.ok'),
      cancelText: '',
      type: 'info'
    };
    this.confirmationModal.show(successData);
  }

  showErrorMessage(message: string) {
    const errorData: ConfirmationModalData = {
      title: this.translationService.translate('common.error'),
      message: message,
      confirmText: this.translationService.translate('common.ok'),
      cancelText: '',
      type: 'warning'
    };
    this.confirmationModal.show(errorData);
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  isRTL(): boolean {
    return this.translationService.isRTL();
  }

  get totalPages(): number {
    return Math.ceil(this.totalCount / this.pageSize);
  }

  get pages(): number[] {
    const pages: number[] = [];
    const maxVisiblePages = 5;
    
    if (this.totalPages === 0) {
      pages.push(1);
      return pages;
    }
    
    let startPage = Math.max(1, this.currentPage - Math.floor(maxVisiblePages / 2));
    let endPage = Math.min(this.totalPages, startPage + maxVisiblePages - 1);
    
    if (endPage - startPage + 1 < maxVisiblePages) {
      startPage = Math.max(1, endPage - maxVisiblePages + 1);
    }
    
    for (let i = startPage; i <= endPage; i++) {
      pages.push(i);
    }
    
    return pages;
  }

  get Math() {
    return Math;
  }

  formatDate(dateString: string): string {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleDateString();
  }

  getTypeBadgeClass(type: number): string {
    switch (type) {
      case DocumentType.Letter:
        return 'badge-letter'; // Blue gradient
      case DocumentType.Task:
        return 'badge-task'; // Green gradient
      case DocumentType.Meeting:
        return 'badge-meeting'; // Orange gradient
      case DocumentType.Minute:
        return 'badge-minute'; // Purple gradient
      case DocumentType.Contract:
        return 'badge-contract'; // Red gradient
      case DocumentType.Report:
        return 'badge-report'; // Teal gradient
      case DocumentType.Image:
        return 'badge-image'; // Pink gradient
      case DocumentType.Scan:
        return 'badge-scan'; // Indigo gradient
      case DocumentType.Other:
        return 'badge-other'; // Gray gradient
      default:
        return 'badge-other';
    }
  }

  getDocumentSourceBadgeClass(source: number): string {
    switch (source) {
      case DocumentSource.Internal:
        return 'badge-internal';
      case DocumentSource.External:
        return 'badge-external';
      default:
        return 'badge-unknown-source';
    }
  }

  formatFileSize(bytes: number): string {
    if (bytes === 0) return this.translate('documents.0_bytes');
    const k = 1024;
    const sizes = [this.translate('documents.bytes'), this.translate('documents.kb'), this.translate('documents.mb'), this.translate('documents.gb')];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }
}
